\set ON_ERROR_STOP on
create schema auth;
do $$ begin if not exists(select 1 from pg_roles where rolname='anon') then create role anon; end if; if not exists(select 1 from pg_roles where rolname='authenticated') then create role authenticated; end if; end $$;
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('test.actor',true),'')::uuid $$;
create table profiles(id uuid,tenant_id uuid,is_active boolean);
create table branches(id uuid,tenant_id uuid,is_active boolean);
create table customers(id uuid,tenant_id uuid);
create table suppliers(id uuid,tenant_id uuid);
create table invoices(id uuid,tenant_id uuid,branch_id uuid,customer_id uuid,code text,created_at timestamptz,status text,deleted_at timestamptz,total numeric,debt numeric,note text);
create table purchase_orders(id uuid,tenant_id uuid,branch_id uuid,supplier_id uuid,code text,created_at timestamptz,status text,total numeric,debt numeric,note text);
create table sales_returns(id uuid,tenant_id uuid,branch_id uuid,customer_id uuid,code text,created_at timestamptz,status text,total numeric,note text);
create table supplier_returns(id uuid,tenant_id uuid,branch_id uuid,supplier_id uuid,code text,created_at timestamptz,status text,total numeric,note text);
create table debt_opening_balances(id uuid,tenant_id uuid,branch_id uuid,party_type text,customer_id uuid,supplier_id uuid,opening_date date,created_at timestamptz,amount numeric,note text);
create table customer_debt_adjustments(id uuid,tenant_id uuid,branch_id uuid,customer_id uuid,cash_transaction_id uuid,idempotency_key text,created_at timestamptz,amount numeric,reason text);
create table cash_transactions(id uuid,tenant_id uuid,branch_id uuid,customer_id uuid,supplier_id uuid,reference_type text,reference_id uuid,category text,type text,code text,transaction_date date,created_at timestamptz,status text,amount numeric,note text);
create table customer_advance_allocations(id uuid,tenant_id uuid,branch_id uuid,invoice_id uuid,created_at timestamptz,amount numeric,note text);
create table supplier_advance_allocations(id uuid,tenant_id uuid,branch_id uuid,purchase_order_id uuid,created_at timestamptz,amount numeric,note text);
create function user_has_permission(uuid,text) returns boolean language sql stable as $$ select coalesce(current_setting('test.denied_permission',true),'')<>$2 $$;
create function user_has_branch_access(uuid,uuid) returns boolean language sql stable as $$ select exists(select 1 from branches b join profiles p on p.tenant_id=b.tenant_id where p.id=$1 and b.id=$2) and coalesce(current_setting('test.denied_branch',true),'')<>$2::text $$;
create function assert_report_access(text,uuid) returns void language plpgsql as $$ begin if not user_has_branch_access(auth.uid(),$2) or not user_has_permission(auth.uid(),$1) then raise exception 'denied' using errcode='42501'; end if; end $$;
create function get_counterparty_balance_summary(uuid) returns jsonb language sql stable as $$ select jsonb_build_object('customers',jsonb_build_array(jsonb_build_object('party_id','40000000-0000-0000-0000-000000000001','debt',500,'advance',100)),'suppliers','[]'::jsonb) $$;
