 begin perform get_party_debt_movements('customer','40000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000002','2026-10-01','2026-10-31'); raise exception 'foreign branch allowed'; exception when insufficient_privilege then null; end;
